B.c1f=new A.ao(B.Do,["\u0639\u0631\u0636 \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0648\u0635\u0644\u0627\u062d\u064a\u0627\u062a\u0647\u0627.","\u0625\u0646\u0634\u0627\u0621 \u0648\u062a\u0639\u062f\u064a\u0644 \u0648\u062d\u0630\u0641 \u0627\u0644\u0623\u062f\u0648\u0627\u0631.","\u0639\u0631\u0636 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646.","\u0625\u0636\u0627\u0641\u0629 \u0648\u062a\u0639\u062f\u064a\u0644 \u0648\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646.","\u0639\u0631\u0636 \u0633\u062c\u0644 \u0627\u0644\u062a\u062f\u0642\u064a\u0642.","\u0625\u0646\u0634\u0627\u0621 \u0648\u062a\u0639\u062f\u064a\u0644 \u0648\u062d\u0630\u0641 \u0627\u0644\u0641\u0626\u0627\u062a.","\u0625\u0646\u0634\u0627\u0621 \u0648\u062a\u0639\u062f\u064a\u0644 \u0648\u062d\u0630\u0641 \u0627\u0644\u0645\u0646\u062a\u062c\u0627\u062a.","\u0639\u0631\u0636 \u0645\u0644\u0641\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0648\u062a\u0627\u0631\u064a\u062e\u0647\u0645.","\u062a\u0639\u062f\u064a\u0644 \u062d\u0627\u0644\u0629 \u0627\u0644\u0639\u0645\u064a\u0644 \u0648\u0645\u0644\u0627\u062d\u0638\u0627\u062a\u0647.","\u062a\u0639\u062f\u064a\u0644 \u0643\u0645\u064a\u0627\u062a \u0627\u0644\u0645\u062e\u0632\u0648\u0646.","\u0639\u0631\u0636 \u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0645\u062e\u0632\u0648\u0646.","\u0628\u062f\u0621 \u062a\u062d\u0636\u064a\u0631 \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0648\u062a\u0633\u0644\u064a\u0645\u0647\u0627.","\u0639\u0631\u0636 \u0634\u0627\u0634\u0629 \u0627\u0644\u0645\u0637\u0628\u062e \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629.","\u0639\u0631\u0636 \u062d\u0633\u0627\u0628\u0627\u062a \u0648\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0648\u0644\u0627\u0621.","\u0625\u062f\u0627\u0631\u0629 \u0642\u0648\u0627\u0639\u062f \u0648\u0645\u0643\u0627\u0641\u0622\u062a \u0627\u0644\u0648\u0644\u0627\u0621.","\u0639\u0631\u0636 \u062c\u0645\u064a\u0639 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a.","\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u062d\u0645\u0644\u0627\u062a \u0648\u0625\u0639\u0627\u062f\u0629 \u0625\u0631\u0633\u0627\u0644 Push.","\u062d\u0630\u0641 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0648\u062a\u063a\u064a\u064a\u0631 \u062d\u0627\u0644\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629.","\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u0637\u0644\u0628\u0627\u062a.","\u0639\u0631\u0636 \u0627\u0644\u0637\u0644\u0628\u0627\u062a.","\u062a\u063a\u064a\u064a\u0631 \u062d\u0627\u0644\u0629 \u0627\u0644\u0637\u0644\u0628.","\u0639\u0631\u0636 \u0645\u0639\u0627\u0645\u0644\u0627\u062a \u0627\u0644\u062f\u0641\u0639.","\u0641\u062a\u062d \u0646\u0642\u0637\u0629 \u0627\u0644\u0628\u064a\u0639 \u0648\u0625\u062f\u0627\u0631\u0629 \u0648\u0631\u062f\u064a\u0627\u062a \u0627\u0644\u0643\u0627\u0634\u064a\u0631 \u0648\u062a\u062d\u0635\u064a\u0644 \u0627\u0644\u0645\u062f\u0641\u0648\u0639\u0627\u062a \u0648\u062a\u0642\u0641\u064a\u0644 \u0627\u0644\u062f\u0631\u062c.","\u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0642\u064a\u064a\u0645\u0627\u062a \u0623\u0648 \u0631\u0641\u0636\u0647\u0627.","\u0625\u062f\u0627\u0631\u0629 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642.","\u0627\u0633\u062a\u0647\u0644\u0627\u0643 \u0623\u0643\u0648\u0627\u0628 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643.","\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643\u0627\u062a.","\u0639\u0631\u0636 \u0627\u0644\u0637\u0627\u0648\u0644\u0627\u062a \u0648\u0627\u0644\u063a\u0631\u0641 \u0648\u062d\u062c\u0648\u0632\u0627\u062a \u0627\u0644\u0636\u064a\u0648\u0641.","\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0637\u0627\u0648\u0644\u0627\u062a \u0648\u0627\u0644\u063a\u0631\u0641 \u0648\u062d\u062c\u0648\u0632\u0627\u062a \u0627\u0644\u0636\u064a\u0648\u0641.","\u0641\u062a\u062d \u062f\u0644\u064a\u0644 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u0648\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0644\u0641\u0627\u062a \u062f\u0627\u062e\u0644 \u0627\u0644\u0646\u0637\u0627\u0642.","\u062a\u062d\u0631\u064a\u0631 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u0639\u0627\u0642\u062f \u0648\u0627\u0644\u0642\u0633\u0645 \u0648\u0627\u0644\u0645\u0633\u0645\u0649 \u0648\u0627\u0644\u062d\u0627\u0644\u0629.","\u0639\u0631\u0636 \u0627\u0644\u0628\u0635\u0645\u0629 \u0648\u0627\u0644\u062d\u0636\u0648\u0631 \u0627\u0644\u064a\u0648\u0645\u064a \u0644\u0645\u0646 \u0641\u064a \u0627\u0644\u0646\u0637\u0627\u0642.","\u0645\u0631\u0627\u062c\u0639\u0629 \u062a\u0635\u062d\u064a\u062d\u0627\u062a \u0627\u0644\u062d\u0636\u0648\u0631 \u0648\u0627\u0639\u062a\u0645\u0627\u062f\u0647\u0627.","\u0637\u0644\u0628 \u062a\u0635\u062d\u064a\u062d \u062d\u0636\u0648\u0631 \u0646\u064a\u0627\u0628\u0629 \u0639\u0646 \u0645\u0648\u0638\u0641 \u0622\u062e\u0631.","\u0639\u0631\u0636 \u0627\u0644\u062c\u062f\u0627\u0648\u0644 \u0627\u0644\u0645\u0633\u0648\u062f\u0629 \u0648\u0627\u0644\u0645\u0646\u0634\u0648\u0631\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0646\u0637\u0627\u0642.","\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u062c\u062f\u0627\u0648\u0644 \u0648\u0646\u0634\u0631\u0647\u0627 \u0648\u0625\u0644\u063a\u0627\u0621\u0647\u0627.","\u0627\u0639\u062a\u0645\u0627\u062f \u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0625\u062c\u0627\u0632\u0629 \u0623\u0648 \u0631\u0641\u0636\u0647\u0627 \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0627\u0633\u062a\u062d\u0642\u0627\u0642.","\u0625\u0636\u0627\u0641\u0629 \u0633\u062c\u0644\u0627\u062a \u0623\u062c\u0631 \u0628\u062a\u0627\u0631\u064a\u062e \u0646\u0641\u0627\u0630 \u0644\u0645\u0646 \u0641\u064a \u0627\u0644\u0646\u0637\u0627\u0642.","\u0642\u0631\u0627\u0621\u0629 \u062f\u0648\u0631\u0627\u062a \u0627\u0644\u0631\u0648\u0627\u062a\u0628 \u0648\u0642\u0633\u064a\u0645\u0627\u062a \u0645\u0646 \u0641\u064a \u0627\u0644\u0646\u0637\u0627\u0642.","\u062a\u0648\u0644\u064a\u062f \u062f\u0648\u0631\u0627\u062a \u0627\u0644\u0631\u0648\u0627\u062a\u0628 \u0648\u0625\u0639\u0627\u062f\u0629 \u0627\u062d\u062a\u0633\u0627\u0628\u0647\u0627 \u0648\u0625\u0644\u063a\u0627\u0624\u0647\u0627.","\u0627\u0639\u062a\u0645\u0627\u062f \u062f\u0648\u0631\u0629 \u0631\u0648\u0627\u062a\u0628 \u0645\u062d\u0633\u0648\u0628\u0629.","\u062a\u0633\u062c\u064a\u0644 \u0635\u0631\u0641 \u062f\u0648\u0631\u0629 \u0631\u0648\u0627\u062a\u0628 \u0645\u0639\u062a\u0645\u062f\u0629.","\u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0633\u0644\u0641 \u0648\u0627\u0644\u062a\u0633\u0648\u064a\u0627\u062a \u0648\u0641\u0631\u0648\u0642\u0627\u062a \u0627\u0644\u0635\u0646\u062f\u0648\u0642.","\u062a\u0639\u062f\u064a\u0644 \u0623\u0633\u0639\u0627\u0631 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0648\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0625\u062c\u0627\u0632\u0629 \u0648\u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0632\u0645\u0646\u064a\u0629."],t.l)
